const item = $input.first().json;
const apprenants = item['Apprenants Inscrits'] || [];

if (!Array.isArray(apprenants)) {
  throw new Error('"Apprenants Inscrits" doit être un tableau');
}

function isTomorrow(dateString) {
  if (!dateString) return false;

  const date = new Date(dateString);
  if (isNaN(date.getTime())) return false;

  const now = new Date();

  const today = new Date(now.getFullYear(), now.getMonth(), now.getDate());
  const tomorrow = new Date(today);
  tomorrow.setDate(today.getDate() + 1);

  const target = new Date(date.getFullYear(), date.getMonth(), date.getDate());

  return target.getTime() === tomorrow.getTime();
}

function getEmargementLabel(numeroAtelier) {
  if (!numeroAtelier) return "";

  if (numeroAtelier === 1 || numeroAtelier === 2) return "Émargement visio 1";
  if (numeroAtelier === 3 || numeroAtelier === 4) return "Émargement visio 2";
  if (numeroAtelier === 5 || numeroAtelier === 6) return "Émargement visio 3";
  if (numeroAtelier === 7 || numeroAtelier === 8) return "Émargement visio 4";
  if (numeroAtelier === 9 || numeroAtelier === 10) return "Émargement visio 5";

  return "";
}

let atelierDemain = null;

for (let i = 1; i <= 12; i++) {
  const dateField = item[`Date atelier ${i}`];

  if (isTomorrow(dateField)) {
    atelierDemain = {
      numero: i,
      date: dateField || "",
      lien: item[`Lien Atelier ${i}`] || "",
      id_calendrier: item[`ID Calendrier Atelier ${i}`] || "",
      emargement_a_verifier: getEmargementLabel(i)
    };
    break;
  }
}

return apprenants.map((apprenant, index) => {
  return {
    json: {
      index,
      apprenant,
      atelier_demain_numero: atelierDemain ? atelierDemain.numero : null,
      atelier_demain_date: atelierDemain ? atelierDemain.date : "",
      atelier_demain_lien: atelierDemain ? atelierDemain.lien : "",
      atelier_demain_id_calendrier: atelierDemain ? atelierDemain.id_calendrier : "",
      emargement_a_verifier: atelierDemain ? atelierDemain.emargement_a_verifier : ""
    }
  };
});

return $input.all().map(item => {
  const data = item.json || {};
  const champEmargement = data.emargement_a_verifier || "";

  let statut_emargement = "à envoyer";

  if (champEmargement) {
    const valeur = data[champEmargement];

    const estRempli =
      valeur !== undefined &&
      valeur !== null &&
      (
        (Array.isArray(valeur) && valeur.length > 0) ||
        (!Array.isArray(valeur) && String(valeur).trim() !== "")
      );

    if (estRempli) {
      statut_emargement = "déjà présent";
    }
  }

  return {
    json: {
      id: data.id || "",
      apprenant: data.apprenant || "",
      prenom: data["Prénom"] || "",
      nom: data["Nom"] || "",
      mail: data["Mail"] || "",
      numero: data["Numéro"] || "",
      formation: data["Formation"] || "",
      session: data["Session"] || [],
      atelier_demain_numero: data.atelier_demain_numero || null,
      atelier_demain_date: data.atelier_demain_date || "",
      atelier_demain_lien: data.atelier_demain_lien || "",
      atelier_demain_id_calendrier: data.atelier_demain_id_calendrier || "",
      emargement_a_verifier: champEmargement,
      statut_emargement
    }
  };
});

