const record = $('Get a record2').first().json;

const timeZone = 'Europe/Paris';

function getParisDateParts(date) {
  const parts = new Intl.DateTimeFormat('en-CA', {
    timeZone,
    year: 'numeric',
    month: '2-digit',
    day: '2-digit'
  }).formatToParts(date);

  const map = {};
  for (const part of parts) {
    if (part.type !== 'literal') {
      map[part.type] = part.value;
    }
  }

  return {
    year: Number(map.year),
    month: Number(map.month),
    day: Number(map.day),
  };
}

function toParisYMD(date) {
  const p = getParisDateParts(date);
  return `${p.year}-${String(p.month).padStart(2, '0')}-${String(p.day).padStart(2, '0')}`;
}

const now = new Date();
const tomorrow = new Date(now);
tomorrow.setDate(tomorrow.getDate() + 1);

const tomorrowYMD = toParisYMD(tomorrow);

let lienAtelier = '';

for (let i = 1; i <= 10; i++) {
  const dateAtelier = record[`Date atelier ${i}`];
  const lien = record[`Lien Atelier ${i}`];

  if (!dateAtelier) continue;

  const atelierDate = toParisYMD(new Date(dateAtelier));

  if (atelierDate === tomorrowYMD) {
    lienAtelier = lien || '';
    break;
  }
}

return [
  {
    json: {
      lienAtelier
    }
  }
];

