const items = $input.all();

function getNodeFirst(nodeName) {
  try {
    return $(nodeName).first();
  } catch (e) {
    return null;
  }
}

function findFields(currentJson, loopJson) {
  return (
    currentJson?.body?.fields ||
    currentJson?.fields ||
    loopJson?.body?.fields ||
    loopJson?.fields ||
    {}
  );
}

function parisDateYYYYMMDD(date) {
  return new Intl.DateTimeFormat('fr-CA', {
    timeZone: 'Europe/Paris',
    year: 'numeric',
    month: '2-digit',
    day: '2-digit',
  }).format(date);
}

function normalizeDate(value) {
  if (!value) return null;

  const date = new Date(value);

  if (!isNaN(date.getTime())) {
    return parisDateYYYYMMDD(date);
  }

  return String(value).slice(0, 10);
}

const loopItem = getNodeFirst('Loop Over Items2');
const loopJson = loopItem?.json || {};

const tomorrow = new Date();
tomorrow.setDate(tomorrow.getDate() + 1);

const demain = parisDateYYYYMMDD(tomorrow);

return items.map((item) => {
  const json = item.json || {};

  const formateurs = json.Formateur || [];

  const formateur1 = Array.isArray(formateurs) ? formateurs[0] : formateurs;
  const formateur2 = Array.isArray(formateurs) ? formateurs[1] : null;

  const fields = findFields(json, loopJson);

  const atelierEstDemain = (numero) => {
    const value = fields[`Date atelier ${numero}`];
    return normalizeDate(value) === demain;
  };

  let formateurChoisi = formateur1;

  // Si le formateur 2 est Solo / solo, on prend toujours le formateur 1
  if (String(formateur2 || '').trim().toLowerCase() === 'solo') {
    formateurChoisi = formateur1;
  }

  // Ateliers 1 à 8 = formateur 1
  else if ([1, 2, 3, 4, 5, 6, 7, 8].some(atelierEstDemain)) {
    formateurChoisi = formateur1;
  }

  // Ateliers 9 et 10 = formateur 2
  else if ([9, 10].some(atelierEstDemain)) {
    formateurChoisi = formateur2 || formateur1;
  }

  // Ateliers 11 et 12 = formateur 1
  else if ([11, 12].some(atelierEstDemain)) {
    formateurChoisi = formateur1;
  }

  return {
    json: {
      ...json,
      formateurChoisi,
      atelierDemainDetecte: true,
    },
  };
});
